            # Eliminate below
            for k in range(i+1, n):
                factor = matrix[k][i] / matrix[i][i]
                for j in range(n):
                    matrix[k][j] -= factor * matrix[i][j]

        # Back substitution
        x = [0.0] * n
        for i in range(n-1, -1, -1):
            x[i] = matrix[i][-1]
            for k in range(i+1, n):
                x[i] -= matrix[i][k] * x[k]
            x[i] /= matrix[i][i]

        return x

